_PROVIDER_INDEX = {item["id"]: item for item in PROVIDERS}


def list_domain_providers() -> list[dict[str, Any]]:
    return deepcopy(list(PROVIDERS))


def get_domain_provider(provider_id: str) -> dict[str, Any] | None:
    item = _PROVIDER_INDEX.get(str(provider_id).strip().casefold())
    return deepcopy(item) if item is not None else None


def list_domain_categories() -> list[dict[str, Any]]:
    return deepcopy(list(CATEGORIES))

